    pub fn complete_job(&mut self, job_id: Uuid, output_hash: String) -> NclResult<()> {
        let job = self
            .jobs
            .get_mut(&job_id)
            .ok_or_else(|| NclError::JobNotFound(job_id.to_string()))?;
