    pub fn new(guardians: Vec<Guardian>, balance: u128) -> Self {
        Self {
            guardians,
            threshold: MULTISIG_THRESHOLD,
            balance,
            pending: HashMap::new(),
            daily_spent: 0,
            last_reset: Utc::now(),
