/// Appends a compact-u16 value to `buf`.
/// Values 0–127 → 1 byte.  128–16383 → 2 bytes.  16384+ → 3 bytes.
fn write_compact_u16(buf: &mut Vec<u8>, mut n: usize) {
    loop {
        let lower = (n & 0x7f) as u8;
        n >>= 7;
        if n == 0 {
            buf.push(lower);
            break;
        }
        buf.push(lower | 0x80);
    }
}

