    b3_g(st, 0, 4,  8, 12, msg[0],  msg[1]);
    b3_g(st, 1, 5,  9, 13, msg[2],  msg[3]);
    b3_g(st, 2, 6, 10, 14, msg[4],  msg[5]);
    b3_g(st, 3, 7, 11, 15, msg[6],  msg[7]);
    b3_g(st, 0, 5, 10, 15, msg[8],  msg[9]);
