    let mut out = [0u32; 8];
    out.copy_from_slice(&full[..8]);
    out
}

fn load_words(buf: &[u8]) -> [u32; 16] {
    let mut words = [0u32; 16];
    for i in 0..buf.len() {
        words[i / 4] |= (buf[i] as u32) << ((i % 4) * 8);
    }
    words
}

