        match level {
            0 => Some(Self::Dormant),
            1 => Some(Self::Aware),
            2 => Some(Self::Sentient),
            3 => Some(Self::Transcendent),
            4 => Some(Self::Omniscient),
            5 => Some(Self::Cosmic),
            6 => Some(Self::Grok),
