        "pool" => Ok("pool"),
        "solo" => Ok("solo"),
        "benchmark" | "bench" => Ok("benchmark"),
        "dual" => Ok("dual"),
        other => anyhow::bail!(
            "Unsupported miner profile '{}'. Supported profiles: pool, solo, benchmark, dual",
            other
