    pub async fn execute_refund(&self, db: &SwapDb, hash_hex: &str) -> SwapResult<()> {
        let rec = db
            .get_htlc(hash_hex)?
            .ok_or_else(|| SwapError::HtlcNotFound {
                hash_hex: hash_hex.to_string(),
            })?;

        if rec.is_terminal() {
            return Err(SwapError::AlreadySettled {
                hash_hex: hash_hex.to_string(),
                state: rec.state.to_string(),
            });
