    let layer1 = &weights.layers[1];
    ChV4WeightsFlat {
        w1:     layer0.weights.clone(),
        b1:     layer0.bias.clone(),
        w2:     layer1.weights.clone(),
        b2:     layer1.bias.clone(),
        scale1: layer0.scale.clone(),
