            other => panic!("Expected GlobalLimitReached, got {:?}", other),
        }
    }

    #[test]
    fn test_per_address_limit() {
        // max_ops=100, per_address = 100/4 = 25
        let rl = RateLimiter::new(100);
        let addr = "0xSingleUser";
