    fn test_case_insensitive() {
        let rl = RateLimiter::new(100);
        rl.check_and_record("0xABCDEF");
        assert_eq!(rl.current_count(), 1);
        // Same address, different case, should count as same
        rl.check_and_record("0xabcdef");
        assert_eq!(rl.current_count(), 2);
