/// Convert target bytes (32 bytes, big-endian 256-bit) to 8 big-endian uint32 words.
fn target_to_be_words(target: &[u8; 32]) -> [u32; 8] {
    let mut words = [0u32; 8];
    for i in 0..8 {
        words[i] = u32::from_be_bytes([
            target[i * 4],
            target[i * 4 + 1],
            target[i * 4 + 2],
            target[i * 4 + 3],
        ]);
    }
    words
}

