/// Try to receive without blocking. Returns `None` immediately if
    /// nothing is ready.
    pub fn try_next(&mut self) -> Option<BusMessage> {
        loop {
            match self.rx.try_recv() {
                Ok(msg) => {
                    if msg.is_relevant_for(self.agent_id) {
                        return Some(msg);
                    }
                }
                Err(_) => return None,
            }
        }
    }
