    /// Smoothed health score for a pool (simple rolling average).
    pub fn smoothed_score(&self, url: &str) -> f64 {
        let Some(hist) = self.history.get(url) else { return 0.0 };
        if hist.is_empty() {
            return 0.0;
        }
        hist.iter().sum::<f64>() / hist.len() as f64
    }

