        result[i] = (sum >> 32) as u64;
    }

    let mut hash = Hash64::new();
    for (index, value) in result.iter().enumerate() {
        hash.data[index * 8..(index + 1) * 8].copy_from_slice(&value.to_le_bytes());
    }
    hash
