    wallet: WalletFile,
    out: &Path,
    force: bool,
    print: bool,
    set_default: bool,
    password_env: Option<&str>,
) -> Result<()> {
    ensure_output_path(out, force)?;
    let wallet = maybe_encrypt_wallet_file(wallet, password_env)?;
    let json = serde_json::to_string_pretty(&wallet)?;
    write_wallet_file(out, &json)?;

