fn state_to_str(s: &SwapState) -> String {
    match s {
        SwapState::Pending => "pending".into(),
        SwapState::Claimed => "claimed".into(),
        SwapState::Refunded => "refunded".into(),
        SwapState::Error(msg) => format!("error:{msg}"),
