    match s {
        "pending" => SwapState::Pending,
        "claimed" => SwapState::Claimed,
        "refunded" => SwapState::Refunded,
        other => {
            let msg = other.strip_prefix("error:").unwrap_or(other).to_string();
            SwapState::Error(msg)
        }
    }
}

