impl Relayer {
    pub fn new(config: Arc<BridgeConfig>, metrics: Arc<BridgeMetrics>) -> Self {
        let rate_limiter = RateLimiter::new(config.security.max_ops_per_hour);
        Self {
            config,
            rate_limiter,
