/// Blake3 compress: returns all 16 state words.
fn b3_compress(
    cv: &[u32; 8],
    bw: &[u32; 16],
    counter: u64,
    block_len: u32,
    flags: u32,
) -> [u32; 16] {
    let mut st: [u32; 16] = [
        cv[0],
        cv[1],
        cv[2],
        cv[3],
        cv[4],
        cv[5],
        cv[6],
        cv[7],
        BLAKE3_IV[0],
        BLAKE3_IV[1],
        BLAKE3_IV[2],
        BLAKE3_IV[3],
        counter as u32,
        (counter >> 32) as u32,
        block_len,
        flags,
    ];
    let mut msg = *bw;
    for _ in 0..7 {
        b3_round(&mut st, &msg);
        b3_permute(&mut msg);
    }
    st
}

/// Compress and extract chaining value (XOR of upper and lower halves).
fn b3_compress_cv(
    cv: &[u32; 8],
    bw: &[u32; 16],
    counter: u64,
    block_len: u32,
    flags: u32,
) -> [u32; 8] {
    let full = b3_compress(cv, bw, counter, block_len, flags);
    let mut out = [0u32; 8];
    for i in 0..8 {
        out[i] = full[i] ^ full[i + 8];
    }
    out
}

/// Load bytes into 16 LE uint32 words (zero-padded).
fn load_words(data: &[u8]) -> [u32; 16] {
    let mut words = [0u32; 16];
    for i in 0..data.len().min(64) / 4 {
        words[i] = u32::from_le_bytes([
            data[i * 4],
            data[i * 4 + 1],
            data[i * 4 + 2],
            data[i * 4 + 3],
        ]);
    }
    // Handle trailing bytes
    let full_words = data.len().min(64) / 4;
    let remaining = data.len().min(64) - full_words * 4;
    if remaining > 0 {
        let mut w = 0u32;
        for j in 0..remaining {
            w |= (data[full_words * 4 + j] as u32) << (j * 8);
        }
        words[full_words] = w;
    }
    words
}

