/// This is the CPU-side work that enables the GPU to only process 52 bytes per nonce.
pub fn precompute_cv(header: &[u8; 180]) -> [u32; 8] {
    // Block 0 (bytes 0-63): CHUNK_START, counter=0
    let block0 = load_words(&header[0..64]);
