async fn fetch_sequence(
    client: &reqwest::Client,
    horizon_url: &str,
    address: &str,
) -> WarpResult<i64> {
    let url = format!("{}/accounts/{}", horizon_url, address);
    let acc: HorizonAccount = client
        .get(&url)
        .header("Accept", "application/json")
        .send().await
        .map_err(|e| WarpError::AdapterError { chain: "stellar".into(), reason: e.to_string() })?
        .json().await
        .map_err(|e| WarpError::AdapterError { chain: "stellar".into(), reason: e.to_string() })?;
    acc.sequence.parse::<i64>().map_err(|_| WarpError::AdapterError {
        chain: "stellar".into(),
        reason: format!("Cannot parse sequence number: '{}'", acc.sequence),
    })
}

async fn submit_transaction(
    client: &reqwest::Client,
    horizon_url: &str,
    envelope_b64: &str,
) -> WarpResult<String> {
    let url = format!("{}/transactions", horizon_url);
    let resp = client
        .post(&url)
        .header("Content-Type", "application/x-www-form-urlencoded")
        .body(format!(
            "tx={}",
            envelope_b64
                .replace('+', "%2B")
                .replace('/', "%2F")
                .replace('=', "%3D")
        ))
        .send().await
        .map_err(|e| WarpError::AdapterError { chain: "stellar".into(), reason: e.to_string() })?;

    let status = resp.status();
    let body: serde_json::Value = resp.json().await.unwrap_or(serde_json::json!({}));

    if !status.is_success() {
        let reason = body["extras"]["result_codes"].to_string();
        return Err(WarpError::AdapterError {
            chain: "stellar".into(),
            reason: format!("Horizon submit failed HTTP {}: {}", status, reason),
        });
    }

    body["hash"]
        .as_str()
        .map(|s| s.to_string())
        .ok_or_else(|| WarpError::AdapterError {
            chain: "stellar".into(),
            reason: "Missing hash in Horizon response".into(),
        })
}

