/// Cosmos adapter — CosmWASM contract events via CosmosSDK REST.
pub struct CosmosAdapter {
    network: String,
    rest_url: String,
    client: reqwest::Client,
}

impl Default for CosmosAdapter {
    fn default() -> Self { Self::new() }
}

impl CosmosAdapter {
    pub fn new() -> Self {
        let network = std::env::var("COSMOS_NETWORK").unwrap_or_else(|_| "cosmoshub-4".into());
        let rest_url = std::env::var("WARP_COSMOS_REST")
            .unwrap_or_else(|_| default_rest(&network).to_string());
        Self {
            network,
            rest_url,
            client: reqwest::Client::builder()
                .timeout(std::time::Duration::from_secs(15))
                .build()
                .unwrap(),
        }
    }

    async fn latest_height(&self) -> WarpResult<u64> {
        let url = format!("{}/cosmos/base/tendermint/v1beta1/blocks/latest", self.rest_url);
        let resp: CosmosBlockResp = self.client.get(&url).send().await
            .map_err(|e| WarpError::AdapterError { chain: "cosmos".into(), reason: e.to_string() })?
            .json().await
            .map_err(|e| WarpError::AdapterError { chain: "cosmos".into(), reason: e.to_string() })?;
