/// Return all memories from both tiers (newest first).
    pub fn recall_all(&self) -> Vec<MemoryEntry> {
        let mut all = self.long_term.clone();
        all.extend(self.short_term.clone());
        all.sort_by(|a, b| b.timestamp.cmp(&a.timestamp));
