        let sm = self
            .state_machines
            .get_mut(&id)
            .ok_or_else(|| WarpError::TransferNotFound(id.to_string()))?;
        sm.transition(new_status)?;

        let transfer = self
            .transfers
            .get_mut(&id)
            .ok_or_else(|| WarpError::TransferNotFound(id.to_string()))?;
        transfer.status = new_status;
        transfer.updated_at = chrono::Utc::now();

