    ui::print_info(&format!("Restarting service: {}", service));

    let args = if service == "all" {
        vec!["compose", "-f", "V3/docker/docker-compose.yml", "restart"]
    } else {
        vec![
            "compose",
            "-f",
            "V3/docker/docker-compose.yml",
            "restart",
