        let factor = 10u128.checked_pow((to_decimals - from_decimals) as u32)?;
        amount.checked_mul(factor)
    } else {
        let factor = 10u128.checked_pow((from_decimals - to_decimals) as u32)?;
        Some(amount / factor)
    }
