    let mut best_ws = candidates[0];
    let mut best_mhps = 0.0;
    let mut best_device = String::new();

    for &ws in candidates {
        let mut gpu = GpuDcrMiner::new(ws)?;
        let device = gpu.device_name();
        let (_, _, mhps) = gpu.benchmark(secs)?;
        if mhps > best_mhps {
