pub fn validate_outputs(outputs: &[(u64, &str)]) -> Result<(), String> {
    let mut total: u128 = 0;
    for (i, &(amount, _)) in outputs.iter().enumerate() {
        if amount == 0 {
            return Err(format!("output {} has zero amount", i));
        }
        if amount > MAX_OUTPUT_AMOUNT {
            return Err(format!(
