        let entry = self
            .chains
            .get_mut(name)
            .ok_or_else(|| WarpError::UnsupportedChain(name.to_string()))?;
        entry.enabled = false;
        Ok(())
    }

    pub fn enable(&mut self, name: &str) -> WarpResult<()> {
        let entry = self
            .chains
            .get_mut(name)
            .ok_or_else(|| WarpError::UnsupportedChain(name.to_string()))?;
        entry.enabled = true;
        Ok(())
    }

    pub fn is_enabled(&self, name: &str) -> bool {
        self.chains.get(name).map(|e| e.enabled).unwrap_or(false)
    }

