        self.chains
            .values()
            .filter(|e| e.enabled)
            .map(|e| &e.chain_id)
            .collect()
    }

    pub fn list_all(&self) -> Vec<(&String, bool)> {
        self.chains
            .iter()
            .map(|(name, entry)| (name, entry.enabled))
            .collect()
    }

