    tail.copy_from_slice(&header[128..180]);

    let start = Instant::now();
    let mut count: u64 = 0;
    let mut nonce: u32 = 0;

    loop {
        for _ in 0..8192 {
            tail[12..16].copy_from_slice(&nonce.to_le_bytes());
