/// Information about a UTXO needed for validation.
#[derive(Debug, Clone)]
pub struct UtxoInfo {
    pub amount: u64,
    pub address: String,
    /// Height at which this UTXO was created.
    pub created_height: u64,
    /// Whether this UTXO was created by a coinbase transaction.
    pub is_coinbase: bool,
