        };

        let content = format!(
            "Hiranyagarbha {} echo: {}",
            level_label, request.user_prompt
        );

        Ok(LlmResponse::simple(content, self.id()))
    }

    fn generation_count(&self) -> u64 {
        self.generation_count
            .load(std::sync::atomic::Ordering::Relaxed)
    }
