        Self {
            id: Uuid::new_v4(),
            name,
            owner,
            wallet_address,
            capabilities: vec![AgentCapability::Transact],
            status: AgentStatus::Initializing,
            consciousness_level: 0,
            created_at: Utc::now(),
            last_action: None,
            total_actions: 0,
            staked_zion: 0,
        }
    }

