        let vram_pct: usize = std::env::var("ZION_OCL_VRAM_PCT")
            .ok()
            .and_then(|v| v.trim().parse().ok())
            .unwrap_or(25)
            .clamp(10, 90);
        let usable = (global_mem * vram_pct) / 100;
        let max_by_mem = usable / SCRATCHPAD_BYTES;

