pub fn sha3_512_chunks<const N: usize>(chunks: [&[u8]; N]) -> Hash64 {
    let mut hasher = Sha3_512::new();
    for chunk in chunks {
        hasher.update(chunk);
    }

    let result = hasher.finalize();
    let mut hash = Hash64::new();
    hash.data.copy_from_slice(&result);
    hash
