/// Sleep for `seconds`, checking `stop` every second.
/// Returns `true` if stop was requested.
fn wait_or_stop(stop: &AtomicBool, seconds: u64) -> bool {
    for _ in 0..seconds {
        if stop.load(Ordering::Relaxed) {
            return true;
        }
        thread::sleep(Duration::from_secs(1));
    }
    false
