        let tx_hash = cosmic_harmony_ekam_deeksha(tx.tx_id.as_bytes(), tx.nonce);
        for (slot, value) in seed.iter_mut().zip(tx_hash.data.iter()) {
            *slot ^= *value;
        }
    }
    cosmic_harmony_ekam_deeksha(&seed, transactions.len() as u64).data
}

