pub async fn eth_send_raw_tx(
    client: &reqwest::Client,
    rpc_url: &str,
    raw_hex: &str,
) -> WarpResult<String> {
    let body = serde_json::json!({
        "jsonrpc": "2.0",
        "method": "eth_sendRawTransaction",
        "params": [format!("0x{}", raw_hex)],
        "id": 1
    });
    let resp: serde_json::Value = client
        .post(rpc_url)
        .json(&body)
        .send()
        .await
        .map_err(|e| WarpError::AdapterError {
            chain: "evm".into(),
            reason: e.to_string(),
        })?
        .json()
        .await
        .map_err(|e| WarpError::AdapterError {
            chain: "evm".into(),
            reason: e.to_string(),
        })?;

    if let Some(err) = resp.get("error") {
        return Err(WarpError::AdapterError {
            chain: "evm".into(),
            reason: format!("eth_sendRawTransaction error: {}", err),
        });
    }

    let tx_hash = resp["result"]
        .as_str()
        .unwrap_or("")
        .to_string();

    if tx_hash.is_empty() {
        return Err(WarpError::AdapterError {
            chain: "evm".into(),
            reason: "eth_sendRawTransaction returned empty tx hash".into(),
        });
    }

    Ok(tx_hash)
}

