        // 2. Select UTXOs (largest first)
        let (selected, fee) = select_utxos(&confirmed, amount_sats, feerate)?;
        let total_in: u64 = selected.iter().map(|u| u.value).sum();
        let change = total_in - amount_sats - fee;

