    pub fn new() -> Self {
        let network = std::env::var("STELLAR_NETWORK").unwrap_or_else(|_| "mainnet".into());
        let horizon_url = std::env::var("WARP_STELLAR_HORIZON")
            .unwrap_or_else(|_| default_horizon(&network).to_string());
