/// Mine a batch of nonces. Returns found nonces (if any meet target).
    #[allow(dead_code)]
    pub fn mine_batch(
        &mut self,
        header: &[u8; 180],
        target: &[u8; 32],
        nonce_start: u32,
    ) -> Result<Vec<u32>, String> {
        let cv = precompute_cv(header);
        let tail: Vec<u8> = header[128..180].to_vec();
        let target_be = target_to_be_words(target);

        self.cv_buf
            .write(&cv as &[u32])
            .enq()
            .map_err(|e| format!("{e}"))?;
        self.tail_buf
            .write(&tail)
            .enq()
            .map_err(|e| format!("{e}"))?;
        self.target_buf
            .write(&target_be as &[u32])
            .enq()
            .map_err(|e| format!("{e}"))?;

        let zeros = vec![0u32; 1 + MAX_RESULTS as usize];
        self.results_buf
            .write(&zeros)
            .enq()
            .map_err(|e| format!("{e}"))?;

        self.kernel
            .set_arg(3, nonce_start)
            .map_err(|e| format!("{e}"))?;

        unsafe {
            self.kernel.enq().map_err(|e| format!("kernel enq: {e}"))?;
        }

        self.pro_que.queue().finish().map_err(|e| format!("{e}"))?;

        // Read results
        let mut results = vec![0u32; 1 + MAX_RESULTS as usize];
        self.results_buf
            .read(&mut results)
            .enq()
            .map_err(|e| format!("{e}"))?;

        let count = results[0].min(MAX_RESULTS) as usize;
        Ok(results[1..1 + count].to_vec())
    }
