                    params![status_to_str(s)],
                    |row| row.get(0),
                )
                .map_err(|e| NclError::Database(format!("count: {e}")))?,
            None => conn
                .query_row("SELECT COUNT(*) FROM jobs", [], |row| row.get(0))
                .map_err(|e| NclError::Database(format!("count: {e}")))?,
        };
