/// Blake3 compress: returns all 16 state words.
fn b3_compress(
    cv: &[u32; 8],
    bw: &[u32; 16],
    counter: u64,
    block_len: u32,
    flags: u32,
) -> [u32; 16] {
    let mut st: [u32; 16] = [
        cv[0],
        cv[1],
        cv[2],
        cv[3],
        cv[4],
        cv[5],
        cv[6],
        cv[7],
        BLAKE3_IV[0],
        BLAKE3_IV[1],
        BLAKE3_IV[2],
        BLAKE3_IV[3],
        counter as u32,
        (counter >> 32) as u32,
        block_len,
        flags,
    ];
    let mut msg = *bw;
    for _ in 0..7 {
        b3_round(&mut st, &msg);
        b3_permute(&mut msg);
    }
    st
}

