    let requested_backend = backend.unwrap_or_else(|| cfg.miner.backend.clone());
    let normalized_backend = normalize_backend(&requested_backend, true)?;

    Ok(ResolvedStartOptions {
        pool_addr,
        wallet_addr,
        thread_count,
