impl LlmResponse {
    pub fn simple(content: impl Into<String>, backend_id: impl Into<String>) -> Self {
        let content = content.into();
        let completion_tokens = (content.split_whitespace().count() as u32).saturating_add(1);
        Self {
            content,
            prompt_tokens: 0,
            completion_tokens,
            backend_id: backend_id.into(),
            truncated: false,
        }
    }
}

