            if let Some(entry) = self.entries.get(&current) {
                let next = entry.prev_hash;
                if next == current {
                    break;
                }
                current = next;
                depth += 1;
                if depth > MAX_REORG_DEPTH + SOFT_FINALITY_DEPTH {
