fn build_unsigned_tx(
    selected: &[MempoolUtxo],
    recipient: &Address,
    amount: u64,
    change: u64,
    change_addr: &Address,
) -> WarpResult<Transaction> {
    const DUST: u64 = 546; // P2WPKH dust threshold

    let inputs: Vec<TxIn> = selected.iter().map(|u| {
        let txid = Txid::from_str(&u.txid).expect("valid txid");
        TxIn {
            previous_output: OutPoint::new(txid, u.vout),
            script_sig: ScriptBuf::default(),
            sequence: Sequence::MAX,
            witness: Witness::default(),
        }
    }).collect();

    let mut outputs = vec![
        TxOut {
            value: Amount::from_sat(amount),
            script_pubkey: recipient.script_pubkey(),
        }
    ];

    // Add change output only if above dust limit
    if change >= DUST {
        outputs.push(TxOut {
            value: Amount::from_sat(change),
            script_pubkey: change_addr.script_pubkey(),
        });
    }

    Ok(Transaction {
        version: Version::TWO,
        lock_time: LockTime::ZERO,
        input: inputs,
        output: outputs,
    })
}

async fn broadcast_tx(
    client: &reqwest::Client,
    api_url: &str,
    raw_hex: &str,
) -> WarpResult<String> {
    let url = format!("{}/tx", api_url);
    let resp = client
        .post(&url)
        .header("Content-Type", "text/plain")
        .body(raw_hex.to_string())
        .send()
        .await
        .map_err(|e| WarpError::AdapterError { chain: "bitcoin".into(), reason: e.to_string() })?;

    let status = resp.status();
    let body = resp.text().await.unwrap_or_default();

    if !status.is_success() {
        return Err(WarpError::AdapterError {
            chain: "bitcoin".into(),
            reason: format!("Broadcast failed HTTP {}: {}", status, body.trim()),
        });
    }

    // mempool.space returns the txid as plain text on success
    Ok(body.trim().to_string())
}

