        scored.into_iter().take(top_k).map(|(_, doc)| doc).collect()
    }

    /// Vrátí všechna ID v store.
    pub fn ids(&self) -> Vec<&str> {
        self.documents.iter().map(|d| d.id.as_str()).collect()
    }

    /// Vrátí všechny dokumenty v store.
    pub fn all(&self) -> &[RagDocument] {
        &self.documents
    }
