fn b3_xof_squeeze(co: &B3ChunkOut, buf: &mut [u8]) {
    let buf_len = buf.len();
    let mut ob = 0u64;
    let mut written = 0usize;
    while written < buf_len {
        let st = b3_compress(
            &co.input_cv,
            &co.block_words,
            ob,
            co.block_len,
            co.flags | ROOT,
        );
        let to_write = std::cmp::min(64, buf_len - written);
        for i in 0..to_write {
            buf[written + i] = (st[i / 4] >> ((i % 4) * 8)) as u8;
        }
        written += to_write;
        ob += 1;
    }
}

