        if let Ok(extra_raw) = std::env::var("ZION_VALIDATOR_EXTRA_KEYS") {
            let extra_ids: Vec<String> = std::env::var("ZION_VALIDATOR_EXTRA_IDS")
                .ok()
                .map(|ids| ids.split(',').map(|v| v.trim().to_string()).collect())
                .unwrap_or_default();

            for (index, raw_key) in extra_raw
                .split(',')
                .map(str::trim)
                .filter(|k| !k.is_empty())
