/// Kosínusová podobnost dvou vektorů ∈ [-1.0, 1.0].
/// Vrátí 0.0 pro prázdné nebo nulové vektory.
fn cosine_similarity(a: &[f32], b: &[f32]) -> f32 {
    let len = a.len().min(b.len());
    if len == 0 {
        return 0.0;
