fn parse_hash(hex_str: &str) -> [u8; 32] {
    let mut hash = [0u8; 32];
    if hex_str.len() == 64 {
        for (i, byte) in hash.iter_mut().enumerate() {
            *byte = u8::from_str_radix(&hex_str[i * 2..i * 2 + 2], 16).unwrap_or(0);
        }
    }
    hash
