/// Vote N voters for given choice (each with weight), return proposal with totals applied.
fn vote_n(
    engine: &mut VotingEngine,
    proposal: &mut Proposal,
    n: usize,
    choice: VoteChoice,
    weight: u64,
    prefix: &str,
) {
    for i in 1..=n {
        engine
            .cast_vote(
                proposal,
                format!("{}{:04}", prefix, i),
                choice,
                weight,
                None,
            )
            .unwrap();
    }
}

