            },
        );
        Ok(job)
    }

    pub fn expire_stale_jobs(&mut self) -> Vec<u64> {
        let now_ms = Self::now_ms();
        let mut stale_ids = Vec::new();
        self.active_jobs.retain(|job_id, tracked| {
            let expired = now_ms.saturating_sub(tracked.issued_at_ms) >= self.job_ttl_ms;
            if expired {
