        assert_eq!(b.current_ms(), 100);
        // Simulate wait without actually sleeping
        b.current_ms = b.current_ms.saturating_mul(b.multiplier).min(b.max_ms);
        assert_eq!(b.current_ms(), 200);
        b.current_ms = b.current_ms.saturating_mul(b.multiplier).min(b.max_ms);
