/// Count transfers with a given status string.
    pub fn count_by_status(&self, status: &str) -> WarpResult<usize> {
        let conn = self.conn.lock().unwrap();
        let n: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM transfers WHERE status=?1",
                params![status],
                |r| r.get(0),
            )
            .map_err(db_err)?;
        Ok(n as usize)
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Maintenance
