/// Try to register a new peer. Returns false if rejected (full, subnet limit, etc.).
    pub fn register_peer(
        &mut self,
        peer_id: &str,
        addr: IpAddr,
        port: u16,
        direction: PeerDirection,
        now: Instant,
    ) -> bool {
        if self.peers.contains_key(peer_id) {
            return false; // duplicate
        }
        if self.peer_count() >= MAX_PEERS {
            return false;
        }
        if self.subnet_count(&addr) >= MAX_PER_SUBNET {
            return false;
        }

        self.peers.insert(
            peer_id.to_string(),
            PeerState {
                addr,
                port,
                peer_id: peer_id.to_string(),
                direction,
                score: INITIAL_SCORE,
                connected_at: now,
                last_seen: now,
                best_height: 0,
                bytes_sent: 0,
                bytes_received: 0,
                latency_ms: None,
                banned: false,
            },
        );
        true
    }

    /// Unregister a peer (disconnected).
    pub fn unregister_peer(&mut self, peer_id: &str) {
