    let body = serde_json::json!({
        "jsonrpc": "2.0", "id": 1,
        "method": "eth_blockNumber", "params": []
    });
    let resp: RpcResponse<String> = client.post(rpc).json(&body).send().await?.json().await?;
    if let Some(e) = resp.error {
