/// Errors returned by fallible FFI wrappers.
    #[derive(Debug, Clone, PartialEq, Eq)]
    pub enum FfiError {
        /// Caller passed a zero-length input slice. Safe wrappers reject this
        /// because some C entry points dereference `input[0]` unconditionally.
