/// Convenience: decode a base58 string into exactly 32 bytes (panics on bad input).
fn bs58_decode_32(s: &str) -> [u8; 32] {
    bs58::decode(s)
        .into_vec()
        .unwrap_or_default()
        .try_into()
        .unwrap_or([0u8; 32])
