fn test_init_scratchpad() {
    println!("=== Test: init_scratchpad (87 bytes → 256 KiB XOF) ===\n");

    // Construct seed: SHA3-512 output (we use a simple known pattern)
    let seed = [0xABu8; 64];
    let domain = b"EKAM_SCRATCHPAD_INIT_V1";

