impl TronAdapter {
    pub fn new() -> Self {
        let network = std::env::var("TRON_NETWORK").unwrap_or_else(|_| "mainnet".into());
        let api_url = std::env::var("WARP_TRON_API")
            .unwrap_or_else(|_| default_api(&network).to_string());
        let api_key = std::env::var("TRON_API_KEY").ok();
