        layer2_neon(&hidden, &w.w2, &w.b2, &mut output_i32);
    }
    #[cfg(not(target_arch = "aarch64"))]
    {
        layer2_scalar(&hidden, &w.w2, &w.b2, &mut output_i32);
    }

    // LayerNorm pro output
    layer_norm_int8(&mut output_i32, &w.scale2);

    // ──────── RESIDUAL ADD ────────
    for i in 0..64 {
