        let mut pool = OrphanPool::new();
        for i in 0..MAX_ORPHAN_BLOCKS as u8 {
            pool.insert(orphan(i, 255, 1000));
        }
        assert_eq!(pool.len(), MAX_ORPHAN_BLOCKS);
