async fn main() -> Result<()> {
    let cli = Cli::parse();
    let should_open_menu = cli
        .command
        .as_ref()
        .map(|cmd| matches!(cmd, Commands::Menu))
        .unwrap_or(true);

    if should_open_menu {
        if !io::stdin().is_terminal() || !io::stdout().is_terminal() {
            let mut cmd = Cli::command();
