        match self {
            Self::Heed(e) => write!(f, "LMDB error: {e}"),
            Self::Serde(e) => write!(f, "serialization error: {e}"),
            Self::NotFound(k) => write!(f, "not found: {k}"),
            Self::SchemaVersionMismatch { expected, found } => write!(
                f,
