    /// Terminate an agent.
    pub fn terminate_agent(&mut self, agent_id: Uuid) -> AiResult<()> {
        let agent = self
            .agents
            .get_mut(&agent_id)
            .ok_or_else(|| AiError::AgentNotFound(agent_id.to_string()))?;
        agent.status = AgentStatus::Terminated;
        Ok(())
    }

