        "node" | "core" => "core".into(),
        "pool" => "pool".into(),
        "miner" => "miner".into(),
        "agent" | "ai-native" => "ai-native".into(),
        "website" => "website".into(),
        "redis" => "redis".into(),
        "bridge" => "bridge".into(),
