impl ForkChoice {
    /// Create a new fork-choice tracker seeded with a genesis entry.
    pub fn new(genesis_hash: [u8; 32]) -> Self {
        let genesis = ChainEntry {
            height: 0,
            hash: genesis_hash,
            prev_hash: [0u8; 32],
            difficulty: 0,
            total_work: 0,
