    /// `SWAP:LOCK:<hash_hex>:<timeout_min>:<chain>:<counterparty_addr>`
    Lock {
        hash_hex: String,
        timeout_minutes: u64,
        counterparty_chain: String,
        counterparty_addr: String,
    },
    /// `SWAP:CLAIM:<hash_hex>:<preimage_hex>`
