        data.extend_from_slice(&(recipient_len as u64).to_be_bytes());
        // [128..128+padded]: string bytes
        data.extend_from_slice(recipient_bytes);
        data.extend((0..(padded_len - recipient_len)).map(|_| 0u8));
        format!("0x{}", hex::encode(&data))
